from pathlib import Path
import json,html
base=Path(__file__).resolve().parents[1]
data=json.loads((base/'extension/data/aulas_4bim_2026.json').read_text())
raw=json.dumps(data['postagens'],ensure_ascii=False).replace('</','<\\/')
htmltemplate='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda E-Class · 4º bimestre 2026</title><style>
:root{--ink:#20344c;--blue:#15365c;--gold:#d2a33b;--bg:#f5f7fa;--muted:#687991}*{box-sizing:border-box}body{background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,Arial;margin:0}header{padding:35px max(25px,calc((100vw - 1200px)/2));background:var(--blue);color:white}header small{letter-spacing:1px;color:#b6d2e0;font-weight:700}h1{margin:8px 0 0;font-size:30px}header p{margin:0;color:#d9e5f2}.main{max-width:1200px;margin:0 auto;padding:22px}section.panel{background:white;padding:17px 20px;border-radius:12px;border:1px solid #dce4ee;margin-bottom:16px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{border-radius:10px;padding:16px;border:1px solid #d8e3f0;background:white}.card b{display:block;font-size:27px}.card small{color:#637386}h2{margin:0 0 10px;font-size:19px}label{display:inline-flex;flex-direction:column;margin-right:10px;font-size:12px;font-weight:700;color:#54667b}select,input{margin-top:4px;padding:8px;border:1px solid #cbd7e4;border-radius:7px;background:white;min-width:140px}table{border-collapse:collapse;width:100%;background:white}td,th{padding:9px 11px;border-bottom:1px solid #e9eef2;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#eaf1f8;font-size:12px}td{font-size:13px}.pill{display:inline-block;border-radius:10px;background:#e4f0e7;color:#206333;padding:2px 7px;font-size:11px}.pill.warning{background:#fff1d1;color:#9b5716}.pill.block{background:#fce7e5;color:#a83030}button{background:#215a91;color:#fff;border:0;border-radius:8px;padding:7px 12px;cursor:pointer}.note{background:#fff9e8;border-left:3px solid #be8f2e;padding:11px 14px;margin-bottom:16px}dialog{width:min(900px,94vw);height:90vh;border:0;border-radius:12px;padding:0}dialog::backdrop{background:#091729ac}.modalhead{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #d2dce6}.modalhead h2{font-size:17px;margin:0}iframe{width:100%;height:calc(90vh - 65px);border:0}@media print{header{padding:12px;background:white;color:#000}button{display:none}input,select{display:none}.cards{display:none}.main{max-width:none;padding:4px}th{position:static}}
</style></head><body><header><small>COLÉGIO ADVENTISTA DE ITABUNA · PLANEJAMENTO</small><h1>Agenda de aulas do 4º bimestre</h1><p>21/09 a 11/12/2026 · Matemática, Investigação Matemática e Filosofia</p></header><main class="main"><section class="cards" id="stats"></section><section class="panel"><h2>Critérios e limites</h2><div class="note">Dias 12/10, 30/10, 02/11 e 20/11 excluídos. O dia 08/12 permanece letivo na ausência de indicação do calendário escolar interno. Datas de teste e prova são propostas cronológicas, não confirmação da escola. A condensação de 40 planos de Matemática em 20/34 períodos exige aprovação.</div><label>Turma<select id="turma"><option value="">Todas</option><option>1MA</option><option>1MB</option><option>2MA</option><option>2MB</option><option>3MA</option><option>3MB</option></select></label><label>Disciplina<select id="disciplina"><option value="">Todas</option><option>Matemática</option><option>Investigação Matemática</option><option>Filosofia</option></select></label><label>Status<select id="status"><option value="">Todos</option><option value="pronto_para_conferencia">Para conferência</option><option value="revisao_pedagogica">Condensadas</option><option value="proposta_para_aprovacao">Propostas a revisar</option></select></label><label>Data inicial<input id="from" type="date" value="2026-09-21"></label><label>Data final<input id="to" type="date" value="2026-12-11"></label></section><section class="panel"><h2>Postagens previstas <span id="count"></span></h2><div style="max-height:650px;overflow:auto"><table><thead><tr><th>Data</th><th>Turma</th><th>Disciplina</th><th>Horário</th><th>Planos</th><th>Situação</th><th>Ação</th></tr></thead><tbody id="rows"></tbody></table></div></section></main><dialog id="modal"><div class="modalhead"><h2 id="modalTitle"></h2><button onclick="document.getElementById('modal').close()">Fechar</button></div><iframe id="preview" sandbox="" title="Prévia de aula"></iframe></dialog><script>const aulas=__JSON__;const $=x=>document.getElementById(x);const cards=[['Postagens',aulas.length],['Períodos',aulas.reduce((s,x)=>s+x.quantidade_periodos,0)],['Matemática',aulas.filter(x=>x.disciplina==='Matemática').length],['Pendentes ou condensadas',aulas.filter(x=>x.status!=='pronto_para_conferencia').length]];$('stats').innerHTML=cards.map(([a,b])=>`<div class="card"><b>${b}</b><small>${a}</small></div>`).join('');function redraw(){const filt=aulas.filter(a=>(!$('turma').value||a.turma===$('turma').value)&&(!$('disciplina').value||a.disciplina===$('disciplina').value)&&(!$('status').value||a.status===$('status').value)&&a.data>=$('from').value&&a.data<=$('to').value);$('rows').replaceChildren();for(const x of filt){const tr=document.createElement('tr');const values=[x.data.split('-').reverse().join('/'),x.turma,x.disciplina,x.horario.map(y=>y.inicio+'–'+y.fim).join(', '),x.planos_originais.join(', ')||'—'];for(const v of values){const td=document.createElement('td');td.textContent=v;tr.append(td)}const td=document.createElement('td');const p=document.createElement('span');p.className='pill'+(x.status==='revisao_pedagogica'?' warning':x.status==='proposta_para_aprovacao'?' block':'');p.textContent=x.status==='pronto_para_conferencia'?'Revisar':x.status==='revisao_pedagogica'?'Condensado':'Proposta';td.append(p);tr.append(td);const b=document.createElement('button');b.textContent='Ver aula';b.onclick=()=>{$('modalTitle').textContent=x.titulo;$('preview').srcdoc=`<meta charset="utf-8"><body style="padding:24px;max-width:760px;margin:auto;font:15px/1.6 Arial">${x.html||('<p>'+x.observacao+'</p>')}</body>`;$('modal').showModal()};const t=document.createElement('td');t.append(b);tr.append(t);$('rows').append(tr)}$('count').textContent='('+filt.length+')';}for(const el of document.querySelectorAll('select,input'))el.addEventListener('change',redraw);redraw();</script></body></html>'''
(base/'relatorios'/'calendario_visual.html').write_text(htmltemplate.replace('__JSON__',raw),encoding='utf-8')
print('Relatório gerado')
